#Requires -Version 7.0
[CmdletBinding()]
param(
    [ValidateSet('Summary', 'Log', 'Bodies', 'Diff', 'Show', 'FileAt', 'NameStatus')]
    [string]$Mode = 'Summary',
    [string]$From = '8e2f62417e0fe46cefd884e8a61024b12860a2cf',
    [string]$To = 'f35b696b090985f1119bca5b1f50187997a86113',
    [string[]]$File = @()
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$repo = '<repo>'
Set-Location -LiteralPath $repo

switch ($Mode) {
    'Summary' {
        'HEAD=' + (git rev-parse HEAD)
        'BRANCH=' + (git rev-parse --abbrev-ref HEAD)
        'STATUS-TRACKED-CHANGES=' + @(git status --porcelain --untracked-files=no).Count
        'UNTRACKED=' + @(git status --porcelain | Where-Object { $_ -like '??*' }).Count
        'RANGE-COMMITS=' + (git rev-list --count "$From..$To")
        git diff --shortstat $From $To
    }
    'Log' { git log --format='%H %cI %aI %s' "$From..$To" }
    'Bodies' { git log --format='=== %H%n%B' "$From..$To" }
    'NameStatus' { git diff --name-status $From $To }
    'Diff' {
        if ($File.Count -gt 0) { git diff $From $To -- @File } else { git diff --stat $From $To }
    }
    'Show' { git show --stat --format='=== %H %cI%n%B' $To }
    'FileAt' {
        foreach ($f in $File) { "=== $To`:$f"; git show "$To`:$f" }
    }
}

