#Requires -Version 7.0
[CmdletBinding()]
param(
    [string]$ZipPath = '<repo>/docs/requirements/requirements-wiki-documents.zip',
    [string[]]$Needle = @('INVITE-COPY-03', 'TR-23-C02', 'hosting-schema.mjs', 'INVITE-COPY-01')
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

Add-Type -AssemblyName System.IO.Compression.FileSystem
'ZIP sha256=' + (Get-FileHash -LiteralPath $ZipPath -Algorithm SHA256).Hash + ' write=' + (Get-Item -LiteralPath $ZipPath).LastWriteTime.ToString('s')
$zip = [System.IO.Compression.ZipFile]::OpenRead($ZipPath)
try {
    'ENTRIES=' + $zip.Entries.Count
    foreach ($entry in $zip.Entries) {
        if ($entry.Length -eq 0) { continue }
        $reader = [System.IO.StreamReader]::new($entry.Open())
        try { $text = $reader.ReadToEnd() } finally { $reader.Dispose() }
        foreach ($n in $Needle) {
            $count = ([regex]::Matches($text, [regex]::Escape($n))).Count
            if ($count -gt 0) { '{0} x{1} in {2}' -f $n, $count, $entry.FullName }
        }
    }
} finally { $zip.Dispose() }

