#Requires -Version 7.0
[CmdletBinding()]
param(
    [ValidateSet('Now', 'Start', 'Verdict', 'Complete', 'History')]
    [Parameter(Mandatory)][string]$Mode,
    [string]$VerdictPath = '<repo>/docs/receipts/hv/20261029T090008-admin-pwa-source-round4.verdict.json'
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

Import-Module powershell-yaml -ErrorAction Stop
$repl = '<home>/github/mcpserver-claude-code-plugin/lib/repl-invoke.ps1'
$workDir = Join-Path $PSScriptRoot 'session-params'
if (-not (Test-Path -LiteralPath $workDir)) { $null = New-Item -ItemType Directory -Path $workDir }
$requestId = 'req-20261029T140016Z-prompt-ba89'
$sessionId = 'ClaudeCode-20261029T140011Z-plugin-session'
Set-Location -LiteralPath '<repo>'

function Invoke-Repl {
    param([Parameter(Mandatory)][string]$Method, [Parameter(Mandatory)][System.Collections.IDictionary]$Params, [Parameter(Mandatory)][string]$Name)
    $path = Join-Path $workDir ($Name + '.yaml')
    ConvertTo-Yaml $Params | Set-Content -LiteralPath $path -Encoding utf8
    $output = & pwsh -NoProfile -NonInteractive -File $repl -Method $Method -ParamsPath $path 2>&1
    $exit = $LASTEXITCODE
    $outPath = Join-Path $workDir ($Name + '.out.txt')
    $output | Set-Content -LiteralPath $outPath -Encoding utf8
    [pscustomobject]@{ name = $Name; method = $Method; exitCode = $exit; outLines = @($output).Count; tail = (@($output) | Select-Object -Last 3) -join ' | ' } | ConvertTo-Json -Compress
}

function Split-Text {
    param([string]$Text, [int]$Size = 6000)
    $parts = [System.Collections.Generic.List[string]]::new()
    for ($i = 0; $i -lt $Text.Length; $i += $Size) { $parts.Add($Text.Substring($i, [Math]::Min($Size, $Text.Length - $i))) }
    return , $parts.ToArray()
}

$utc = [DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ')
switch ($Mode) {
    'Now' { 'LOCAL=' + (Get-Date -Format s) + ' UTC=' + $utc }
    'Start' {
        'LOCAL=' + (Get-Date -Format s)
        $params = [ordered]@{
            requestId      = $requestId
            queryTitle     = 'HV round4: Claude Opus staging-readiness review of wordpairs f35b696'
            interpretation = 'Independent hostile validation (read-only) of source revision f35b696b090985f1119bca5b1f50187997a86113 for staging readiness. Parent Codex-20261027T100516Z-plugin-session / req-20261029T135928Z-prompt-c0e1; earlier retry turn req-20261029T042903Z-prompt-c233. Request receipt docs/receipts/hv/20261029T090008-admin-pwa-source-round4.request.jsonl. No product, requirement, TODO or Git mutations; no subagents; no builds or test runs.'
            tags           = @('hostile-validation', 'admin-pwa-source-round4', 'f35b696', 'parent:Codex-20261027T100516Z-plugin-session', 'parentRequest:req-20261029T135928Z-prompt-c0e1', 'earlierRetry:req-20261029T042903Z-prompt-c233', 'FR-LOBBYDISCOVERY-019', 'TEST-ROOMINVITATIONS-025', 'TR-SCHEMA-PROVISIONING-023', 'TEST-SCHEMAPROVISIONING-123')
        }
        Invoke-Repl -Method 'workflow.sessionlog.updateTurn' -Params $params -Name 'start-update'
        $dialog = [ordered]@{
            requestId   = $requestId
            dialogItems = @(
                [ordered]@{ timestamp = $utc; role = 'model'; category = 'observation'; content = 'Linkage: this reviewer turn is ' + $sessionId + ' / ' + $requestId + ' (hook-opened, persisted true in plugin cache). Parent: Codex-20261027T100516Z-plugin-session / req-20261029T135928Z-prompt-c0e1. Earlier retry turn: req-20261029T042903Z-prompt-c233. add-profile ran first (1 profile file, PROFILE-MERGED.md, 376 lines); full marker and AGENTS.md read; credentials not echoed.' }
            )
        }
        Invoke-Repl -Method 'workflow.sessionlog.appendDialog' -Params $dialog -Name 'start-dialog'
    }
    'Verdict' {
        $verdict = Get-Content -LiteralPath $VerdictPath -Raw | ConvertFrom-Json -AsHashtable
        $items = [System.Collections.Generic.List[object]]::new()
        $prose = [string]$verdict['verdictProse']
        $n = 0
        foreach ($part in (Split-Text -Text $prose)) { $n++; $items.Add([ordered]@{ timestamp = $utc; role = 'model'; category = 'decision'; content = "VERDICT PROSE part $n`n" + $part }) }
        foreach ($it in $verdict['items']) {
            $items.Add([ordered]@{ timestamp = $utc; role = 'model'; category = 'observation'; content = ('{0} [{1}] {2}: {3} | anchors: {4} | finding: {5}' -f $it['id'], $it['surface'], $it['status'], $it['claim'], (@($it['anchors']) -join '; '), $it['finding']) })
        }
        foreach ($f in $verdict['findings']) {
            $items.Add([ordered]@{ timestamp = $utc; role = 'model'; category = 'decision'; content = ($f | ConvertTo-Json -Depth 6 -Compress) })
        }
        $json = Get-Content -LiteralPath $VerdictPath -Raw
        $n = 0
        foreach ($part in (Split-Text -Text $json)) { $n++; $items.Add([ordered]@{ timestamp = $utc; role = 'model'; category = 'tool_result'; content = "VERDICT JSON part $n (file $VerdictPath)`n" + $part }) }
        $batch = 0
        for ($i = 0; $i -lt $items.Count; $i += 12) {
            $batch++
            $slice = @($items[$i..([Math]::Min($i + 11, $items.Count - 1))])
            Invoke-Repl -Method 'workflow.sessionlog.appendDialog' -Params ([ordered]@{ requestId = $requestId; dialogItems = $slice }) -Name ('verdict-dialog-{0:D2}' -f $batch)
        }
        'DIALOG-ITEMS=' + $items.Count + ' BATCHES=' + $batch
        $actions = [System.Collections.Generic.List[object]]::new()
        $order = 0
        foreach ($d in $verdict['designDecisions']) { $order++; $actions.Add([ordered]@{ order = $order; description = [string]$d; type = 'design_decision'; status = 'completed'; filePath = '' }) }
        $order++; $actions.Add([ordered]@{ order = $order; description = 'Wrote complete verdict JSON (built from PowerShell objects).'; type = 'create'; status = 'completed'; filePath = $VerdictPath })
        $order++; $actions.Add([ordered]@{ order = $order; description = 'Read-only review tools (parser and PSScriptAnalyzer clean before each run) and QBrain readbacks; git-ignored by .gitignore:22.'; type = 'create'; status = 'completed'; filePath = 'docs/receipts/hv/claude-opus-round4-tools/' })
        Invoke-Repl -Method 'workflow.sessionlog.appendActions' -Params ([ordered]@{ requestId = $requestId; actions = $actions.ToArray() }) -Name 'verdict-actions'
        Invoke-Repl -Method 'workflow.sessionlog.updateTurn' -Params ([ordered]@{ requestId = $requestId; response = $prose }) -Name 'verdict-update'
    }
    'Complete' {
        $verdict = Get-Content -LiteralPath $VerdictPath -Raw | ConvertFrom-Json -AsHashtable
        Invoke-Repl -Method 'workflow.sessionlog.completeTurn' -Params ([ordered]@{ requestId = $requestId; response = [string]$verdict['verdictProse'] }) -Name 'complete'
    }
    'History' {
        Invoke-Repl -Method 'workflow.sessionlog.queryHistory' -Params ([ordered]@{ agent = 'ClaudeCode'; limit = 5; offset = 0 }) -Name ('history-' + (Get-Date -Format 'yyyyMMddTHHmmss'))
    }
}

